package com.gonzalo.shai

/*
 * El banco del modo prueba: lo que escriben las plantillas cuando no escribe Claude. Escrito a mano, con su contexto (quién, dónde, qué se
 * dijo, por qué importa), sus decisiones con tres opciones y la consecuencia de cada una (y de no contestar). Huecos que se rellenan con
 * los de tu carrera:
 *   {A} apodo o nombre · {N} nombre completo · {C} club · {R} rival · {MAR} marcador · {COMP} competición · {G} goles · {AS} asistencias · {NOTA}
 *   {M} su madre (o quien sea de la familia) · {REP} representante · {AMI} amigo de siempre · {EX} la ex · {PER} periodista · {COMP2} compañero
 *   {MED} el medio que le cubre (según su nivel) · {MEDR} el de cotilleo · {TV} el programa de televisión · {xS} x sueldos semanales en euros
 * Nada del campo inventado; ninguna persona real; las mujeres, inventadas; prensa rosa, nada explícito.
 */

/** Lo que cambia (los nombres de [rel] son huecos: «{M}», «{EX}»…). [sueldos]: dinero en sueldos semanales (negativo, gasto). */
class EfP(val sueldos: Double = 0.0, val fama: Int = 0, val aficion: Int = 0, val disciplina: Int = 0, val carisma: Int = 0, val rel: Map<String, Int> = emptyMap())

/** Una opción de una decisión: lo que hace, lo que pasa y lo que cambia. */
class OpP(val texto: String, val pasa: String, val ef: EfP)

/**
 * Una cosa que pasa con su decisión. [tipo]: 1 personal, 2 imagen y dinero, 3 tras el partido (prensa), 4 vacaciones. [cuando] (solo los
 * de tipo 3): "" siempre, "V" victoria, "D" derrota, "E" empate, "G" si marcó. [nivelMax]: hasta qué nivel pega (0 canterano … 4 leyenda).
 */
class EvP(
    val id: String, val tipo: Int, val titulo: String, val texto: String, val de: String, val pregunta: String, val enJuego: String,
    val ops: List<OpP>, val ignorar: String, val efIgnorar: EfP,
    val post: Pair<String, String>, val chat: String, val dms: List<Pair<String, String>>,
    val cuando: String = "", val nivelMin: Int = 0, val nivelMax: Int = 4, val nueva: Triple<String, String, String>? = null,
)

