    // ---------------------------------------------------------------- tras el partido (tipo 3: las decisiones de la prensa)

    val PRENSA = listOf(
        EvP("d_declaraciones", 3, "{PER} quiere tus palabras",
            "{PER}, de {MED}, te ha esperado en la zona mixta después del {MAR} ante el {R} y te ha hecho la pregunta que nadie se atreve a hacer: «¿Te sientes valorado en el {C}?». Tienes el micrófono delante, la cámara grabando y a {REP} haciéndote gestos desde el fondo para que no digas nada. Lo que contestes va a abrir el diario de mañana.",
            "{PER}", "¿Qué le contestas?", "Tu relación con el club, la afición y la prensa",
            listOf(
                OpP("«Aquí soy feliz y quiero ganar algo con este escudo»",
                    "La frase abre {MED} con tu foto besando el escudo. La grada la canta en el siguiente partido. Al club le encanta; a {REP}, que quería apretar en la renovación, bastante menos.",
                    EfP(aficion = 6, carisma = 2, rel = mapOf("{REP}" to -3))),
                OpP("«Eso tendrás que preguntárselo al club»",
                    "La frase se interpreta como un aviso. {MED} titula «{A} lanza un mensaje al club» y los rumores de salida se disparan. {REP} te manda un pulgar hacia arriba.",
